define("mod_bookit/room_overview_filter",[],function(){return{init:function(){const e=document.querySelector('[data-region="room-overview-filter"]'),t=document.querySelectorAll('[data-region="room-overview-row"]');if(!e||!t.length)return;e.addEventListener("change",function(){const n=Array.prototype.map.call(e.selectedOptions,function(e){return e.value});t.forEach(function(e){const t=e.getAttribute("data-room-id");e.hidden=n.length>0&&-1===n.indexOf(t)})})}}});
